package ca.quebec.oui;

import android.app.Activity;
import android.content.Intent;
import android.graphics.Color;
import android.graphics.Typeface;
import android.net.Uri;
import android.os.Bundle;
import android.view.View;
import android.widget.Button;
import android.widget.HorizontalScrollView;
import android.widget.LinearLayout;
import android.widget.ScrollView;
import android.widget.SeekBar;
import android.widget.TextView;
import java.text.DecimalFormat;
import java.util.Locale;

public class MainActivity extends Activity {
    private static final int BLUE=Color.rgb(0,61,165), DARK=Color.rgb(0,31,91), INK=Color.rgb(11,23,57), MUTED=Color.rgb(83,98,122), SOFT=Color.rgb(243,246,251), OFFICIAL=Color.rgb(23,114,69), ESTIMATE=Color.rgb(184,92,0), INFO=Color.rgb(33,91,177);
    private LinearLayout content;
    private final DecimalFormat one=new DecimalFormat("0.0");

    @Override public void onCreate(Bundle b){super.onCreate(b);Locale.setDefault(Locale.CANADA_FRENCH);shell();dashboard();}
    private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}
    private TextView tx(String s,int sp,int c,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(sp);t.setTextColor(c);t.setLineSpacing(0,1.08f);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}
    private Button nav(String s,View.OnClickListener l){Button b=new Button(this);b.setText(s);b.setTextColor(Color.WHITE);b.setAllCaps(false);b.setOnClickListener(l);return b;}

    private void shell(){
        LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Color.WHITE);
        LinearLayout head=new LinearLayout(this);head.setOrientation(LinearLayout.VERTICAL);head.setPadding(dp(18),dp(18),dp(18),dp(14));head.setBackgroundColor(DARK);
        head.addView(tx("⚜  OUI QUÉBEC",26,Color.WHITE,true));head.addView(tx("Données publiques • Québec–Canada • Simulation d'un Québec pays",13,Color.rgb(210,225,255),false));root.addView(head);
        HorizontalScrollView hs=new HorizontalScrollView(this);hs.setHorizontalScrollBarEnabled(false);LinearLayout n=new LinearLayout(this);n.setBackgroundColor(BLUE);n.setPadding(dp(6),dp(6),dp(6),dp(6));
        n.addView(nav("Tableau",v->dashboard()));n.addView(nav("Simulation",v->simulation()));n.addView(nav("Ministères",v->ministries()));n.addView(nav("Actifs fédéraux",v->assets()));n.addView(nav("Saint-Laurent",v->stLawrence()));n.addView(nav("Québec–Canada",v->quebecCanada()));n.addView(nav("Sources",v->sources()));hs.addView(n);root.addView(hs);
        ScrollView sv=new ScrollView(this);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(dp(16),dp(16),dp(16),dp(30));sv.addView(content);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);
    }

    private void reset(String h,String s){content.removeAllViews();content.addView(tx(h,25,INK,true));TextView sub=tx(s,14,MUTED,false);sub.setPadding(0,dp(4),0,dp(14));content.addView(sub);}
    private void card(String title,String big,String detail,boolean official){LinearLayout b=new LinearLayout(this);b.setOrientation(LinearLayout.VERTICAL);b.setPadding(dp(14),dp(12),dp(14),dp(12));b.setBackgroundColor(SOFT);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,0,0,dp(10));b.setLayoutParams(lp);b.addView(tx(title,14,MUTED,true));b.addView(tx(big,27,INK,true));b.addView(tx(detail,13,MUTED,false));TextView tag=tx(official?"● DONNÉE OFFICIELLE":"● ESTIMATION / SIMULATION",11,official?OFFICIAL:ESTIMATE,true);tag.setPadding(0,dp(6),0,0);b.addView(tag);content.addView(b);}
    private void note(String s){TextView t=tx("● "+s,12,ESTIMATE,true);t.setPadding(0,dp(5),0,dp(8));content.addView(t);}
    private void info(String s){TextView t=tx("● "+s,12,INFO,true);t.setPadding(0,dp(5),0,dp(8));content.addView(t);}

    private void dashboard(){reset("Québec en chiffres","Base V2 : données officielles 2026-2027 et résultats 2025 disponibles au 9 septembre 2026.");card("Revenus du Québec","166,492 G$","134,361 G$ de revenus autonomes + 32,131 G$ de transferts fédéraux.",true);card("Dépenses du Québec","170,757 G$","160,489 G$ de dépenses de portefeuilles + 10,268 G$ de service de la dette.",true);card("Santé Québec – budget MSSS","60,579 G$","Budget de dépenses 2026-2027 incluant les mesures du Budget.",true);card("Principaux transferts fédéraux","30,256 G$","Santé 12,457 G$ • social 3,892 G$ • péréquation 13,907 G$.",true);card("Port de Montréal – revenus 2025","155,4 M$","34,3 Mt de marchandises et bénéfice net de 24,2 M$.",true);card("Port de Québec – revenus 2025",">75 M$","Bénéfice net de 21,5 M$; plan de modernisation annoncé de 1,7 G$.",true);note("Les scénarios d'indépendance et valeurs d'actifs sont toujours séparés des données officielles.");}

    private void simulation(){
        reset("Si le Québec devenait un pays","Simulation 2026-2027. Les paramètres orange sont des hypothèses modifiables, non des prévisions officielles.");
        final double own=134.361, expenses=170.757;
        TextView a=tx("Revenus fédéraux attribuables au Québec : 90,0 G$",15,INK,true);content.addView(a);SeekBar fa=new SeekBar(this);fa.setMax(800);fa.setProgress(400);content.addView(fa);
        TextView b=tx("Nouvelles fonctions nationales : 65,0 G$",15,INK,true);b.setPadding(0,dp(12),0,0);content.addView(b);SeekBar fn=new SeekBar(this);fn.setMax(600);fn.setProgress(350);content.addView(fn);
        TextView c=tx("Économies de regroupement : 4,0 G$",15,INK,true);c.setPadding(0,dp(12),0,0);content.addView(c);SeekBar sa=new SeekBar(this);sa.setMax(200);sa.setProgress(40);content.addView(sa);
        TextView e=tx("Revenus nets additionnels Saint-Laurent : 0,3 G$",15,INK,true);e.setPadding(0,dp(12),0,0);content.addView(e);SeekBar sl=new SeekBar(this);sl.setMax(30);sl.setProgress(3);content.addView(sl);
        TextView r=tx("",26,INK,true);r.setPadding(0,dp(18),0,dp(6));content.addView(r);TextView d=tx("",14,MUTED,false);content.addView(d);
        Runnable up=()->{double fed=50+fa.getProgress()/10.0, funcs=30+fn.getProgress()/10.0, save=sa.getProgress()/10.0, river=sl.getProgress()/10.0, bal=own+fed-expenses-funcs+save+river;a.setText("Revenus fédéraux attribuables au Québec : "+one.format(fed)+" G$");b.setText("Nouvelles fonctions nationales : "+one.format(funcs)+" G$");c.setText("Économies de regroupement : "+one.format(save)+" G$");e.setText("Revenus nets additionnels Saint-Laurent : "+one.format(river)+" G$");r.setText("Solde simulé : "+(bal>=0?"+":"")+one.format(bal)+" G$");d.setText("Calcul : 134,361 + "+one.format(fed)+" − 170,757 − "+one.format(funcs)+" + "+one.format(save)+" + "+one.format(river)+". Les transferts fédéraux actuels ne sont pas comptés comme revenus d'un Québec indépendant.");};
        SeekBar.OnSeekBarChangeListener l=new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int p,boolean f){up.run();}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}};fa.setOnSeekBarChangeListener(l);fn.setOnSeekBarChangeListener(l);sa.setOnSeekBarChangeListener(l);sl.setOnSeekBarChangeListener(l);up.run();note("Le Saint-Laurent est traité comme un scénario de recettes nettes potentielles; les recettes brutes ne doivent pas être confondues avec un gain budgétaire net.");
    }

    private void ministry(String area,String qc,String ca,String qcBudget,String caBudget,String impact){LinearLayout b=new LinearLayout(this);b.setOrientation(LinearLayout.VERTICAL);b.setPadding(dp(14),dp(12),dp(14),dp(12));b.setBackgroundColor(SOFT);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,0,0,dp(10));b.setLayoutParams(lp);b.addView(tx(area,18,INK,true));b.addView(tx("QUÉBEC  •  "+qc,13,BLUE,true));b.addView(tx(qcBudget,12,MUTED,false));TextView caT=tx("CANADA  •  "+ca,13,Color.rgb(150,35,45),true);caT.setPadding(0,dp(6),0,0);b.addView(caT);b.addView(tx(caBudget,12,MUTED,false));TextView im=tx(impact,13,ESTIMATE,true);im.setPadding(0,dp(7),0,0);b.addView(im);content.addView(b);}
    private void ministries(){reset("Deux appareils d'État sur un territoire","Comparaison fonctionnelle. Une mission en double ne signifie pas que toute la dépense fédérale disparaîtrait : certaines fonctions seraient reprises par un Québec pays.");ministry("Santé","Ministère de la Santé et des Services sociaux / Santé Québec","Santé Canada","Québec : budget MSSS 2026-2027 de 60,579 G$.","Canada : Santé Canada prévoit 10,979 G$ en 2026-2027, à l'échelle canadienne.","À analyser : réglementation, données, transferts, santé publique, médicaments et services aux clientèles fédérales.");ministry("Revenu / fiscalité","Revenu Québec","Agence du revenu du Canada","Québec administre déjà impôt provincial, TVQ et plusieurs programmes.","Canada administre impôt fédéral, TPS et prestations fiscales fédérales.","Potentiel majeur de guichet fiscal unique; économies administratives à chiffrer séparément.");ministry("Immigration","MIFI","Immigration, Réfugiés et Citoyenneté Canada","Québec sélectionne déjà une part importante de son immigration économique et administre la francisation.","Le fédéral conserve notamment admission finale, citoyenneté, réfugiés et plusieurs contrôles nationaux.","Un Québec pays reprendrait citoyenneté, visas et admission finale : transfert plutôt que suppression complète.");ministry("Finances","Ministère des Finances du Québec","Ministère des Finances Canada","Deux administrations budgétaires, fiscales et économiques distinctes.","Le fédéral gère aussi dette, fiscalité fédérale et transferts.","Fusion partielle; un État souverain doit néanmoins conserver un ministère des Finances complet.");ministry("Ressources naturelles","MRNF","Ressources naturelles Canada","Québec : 827,3 M$ de dépenses prévues en 2026-2027, incluant mesures et infrastructures subventionnées.","Canada : RNCan prévoit 4,879 G$ et 5 401 ETP en 2026-2027 à l'échelle canadienne.","Chevauchement en énergie, mines, forêt, géoscience et cartographie; plusieurs fonctions fédérales devraient être nationalisées au Québec.");ministry("Environnement","MELCCFP","Environnement et Changement climatique Canada","Réglementation provinciale, eau, climat, biodiversité et inspections.","Réglementation fédérale, météo, pollution transfrontalière et engagements internationaux.","Une partie est regroupable; météo et engagements internationaux demeurent nécessaires.");ministry("Transport / infrastructures","Transports et Mobilité durable Québec","Transports Canada / Infrastructure Canada","Réseau routier, transport collectif et réglementation provinciale.","Aviation, ferroviaire interprovincial, maritime, ports fédéraux et programmes d'infrastructure.","Transfert d'actifs et de responsabilités; le coût d'entretien doit accompagner toute valeur d'actif.");ministry("Statistiques","Institut de la statistique du Québec","Statistique Canada","Statistiques québécoises détaillées.","Recensement, comptes nationaux, commerce et séries pancanadiennes.","Regroupement possible, mais un pays doit maintenir un institut statistique national complet.");}

    private void asset(String name,String status,String value,String detail,boolean official){LinearLayout b=new LinearLayout(this);b.setOrientation(LinearLayout.VERTICAL);b.setPadding(dp(14),dp(12),dp(14),dp(12));b.setBackgroundColor(SOFT);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,0,0,dp(10));b.setLayoutParams(lp);b.addView(tx(name,18,INK,true));b.addView(tx(status,12,MUTED,true));b.addView(tx(value,20,official?OFFICIAL:ESTIMATE,true));b.addView(tx(detail,13,MUTED,false));b.addView(tx(official?"● DONNÉE PUBLIQUE":"● ESTIMATION À RAFFINER",11,official?OFFICIAL:ESTIMATE,true));content.addView(b);}
    private void assets(){reset("Actifs fédéraux situés au Québec","Inventaire à compléter actif par actif. La valeur économique n'est pas la même chose que la valeur comptable, le coût de remplacement ou le prix de marché.");asset("Port de Montréal","Administration portuaire fédérale","Revenus 2025 : 155,4 M$","Bénéfice net 24,2 M$; investissements 2025 de 187 M$. La valeur totale de l'actif sera tirée du bilan annuel, pas inventée.",true);asset("Port de Québec","Administration portuaire fédérale","Plan de modernisation : 1,7 G$","Revenus 2025 supérieurs à 75 M$; bénéfice net 21,5 M$. Le plan de modernisation donne un ordre de grandeur d'investissements, pas la valeur de l'actif existant.",true);asset("Voie maritime du Saint-Laurent","Infrastructure fédérale / binationale","Valeur à établir","Écluses, canaux, ouvrages de contrôle, bâtiments, terrains et équipements. L'application distinguera valeur comptable, remplacement et revenus de péage.",false);asset("Aéroports et terrains fédéraux","Actifs et baux variés","Inventaire à établir","Aéroports, terrains, installations de navigation et immeubles fédéraux seront ajoutés avec propriétaire, gestionnaire, superficie et méthode d'évaluation.",false);asset("Immeubles fédéraux","Bureaux, laboratoires, pénitenciers, bases et entrepôts","Inventaire à établir","Chaque fiche devra indiquer valeur comptable lorsqu'elle est publiée, coût de remplacement estimé et dépenses annuelles d'entretien.",false);asset("Ponts et ouvrages fédéraux","Ponts, quais, canaux et autres ouvrages","Inventaire à établir","La valeur brute ne sera jamais comptée comme un gain gratuit : dette, entretien, remise à niveau et obligations associées seront présentés en parallèle.",false);info("Objectif V2+ : importer le Répertoire des biens immobiliers fédéraux et produire le total Québec par catégorie, avec méthode et date d'évaluation.");}

    private void stLawrence(){reset("Contrôle du Saint-Laurent","Le gain potentiel vient surtout des droits, revenus portuaires, politique maritime et retombées logistiques. Il ne faut pas compter toute l'activité économique comme revenu du gouvernement.");card("Port de Montréal – revenus 2025","155,4 M$","Revenus d'exploitation; bénéfice net 24,2 M$; 34,3 Mt de marchandises.",true);card("Port de Québec – revenus 2025",">75 M$","Bénéfice net 21,5 M$; performance financière record annoncée en 2026.",true);asset("Péages et navigation","Scénario Québec pays","0 à 1,5 G$/an","Plage exploratoire dans le simulateur pour tester des recettes nettes potentielles liées à des droits, services, concessions ou nouvelles politiques. Ce n'est pas une donnée officielle.",false);asset("Ports et concessions","Scénario de transfert","À calculer","Un Québec pays pourrait capter directement certains dividendes, loyers, droits et revenus publics associés aux infrastructures transférées, mais aussi leurs coûts d'entretien et d'investissement.",false);asset("Effet logistique et commercial","Effet économique indirect","Non compté comme revenu budgétaire","Le contrôle réglementaire et stratégique d'un corridor maritime peut soutenir commerce, industrie et investissements. Ces retombées seront modélisées séparément du budget de l'État.",false);note("L'application n'additionne pas la valeur des marchandises qui transitent sur le fleuve aux revenus du gouvernement : ce serait économiquement faux.");}

    private void quebecCanada(){reset("Rapport Québec–Canada","Les transferts ne représentent pas à eux seuls le bilan fiscal Québec–Ottawa.");card("Santé","12,457 G$","Transfert canadien en matière de santé, 2026-2027.",true);card("Programmes sociaux","3,892 G$","Transfert canadien en matière de programmes sociaux, 2026-2027.",true);card("Péréquation","13,907 G$","Montant prévu pour 2026-2027.",true);card("Principaux transferts – total","30,256 G$","Le budget du Québec comptabilise 32,131 G$ de transferts fédéraux au total; le périmètre est plus large.",true);info("La prochaine étape chiffrée est la ventilation des impôts fédéraux payés au Québec, TPS, assurance-emploi, pensions et dépenses fédérales territorialisées.");}

    private void source(String title,String detail,String url){LinearLayout b=new LinearLayout(this);b.setOrientation(LinearLayout.VERTICAL);b.setPadding(dp(14),dp(12),dp(14),dp(12));b.setBackgroundColor(SOFT);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,0,0,dp(10));b.setLayoutParams(lp);b.addView(tx(title,17,INK,true));b.addView(tx(detail,13,MUTED,false));Button o=new Button(this);o.setText("Ouvrir la source");o.setAllCaps(false);o.setOnClickListener(v->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url))));b.addView(o);content.addView(b);}
    private void sources(){reset("Sources officielles et institutionnelles","Chaque donnée affichée doit conserver sa source, sa période et son périmètre.");source("Budget du Québec 2026-2027","Revenus, dépenses et cadre financier","https://www.finances.gouv.qc.ca/Budget_et_mise_a_jour/budget/");source("Budget de dépenses du Québec 2026-2027","Portefeuilles ministériels, dont Santé et Ressources naturelles","https://www.quebec.ca/gouvernement/votre-gouvernement/budget-depenses/budget-2026-2027");source("Santé Canada – Plan ministériel 2026-2027","Dépenses prévues : 10,979 G$ à l'échelle canadienne","https://www.canada.ca/fr/sante-canada/organisation/transparence/rapports-gestion/rapport-plans-priorites/2026-2027-plan-ministeriel.html");source("Ressources naturelles Canada – Plan 2026-2027","Dépenses prévues : 4,879 G$; 5 401 ETP","https://ressources-naturelles.canada.ca/organisation/planification-rapports/plan-ministeriel/rncan-2026-2027-plan-ministeriel");source("Principaux transferts fédéraux","Finances Canada – Québec 2026-2027","https://www.canada.ca/fr/ministere-finances/programmes/transferts-federaux/principaux-transferts-federaux.html");source("Port de Montréal – résultats 2025","Revenus, bénéfice, tonnage et investissements","https://www.port-montreal.com/fr/le-port-de-montreal/nouvelles-et-evenements/nouvelles/communiques-de-presse/reunion-annuelle-2026");source("Port de Québec – rapports annuels","Rapport annuel 2025 et résultats financiers","https://www.portquebec.ca/a-propos/rapports-annuels/");source("Voie maritime du Saint-Laurent","Rapports et sommaires corporatifs","https://grandslacs-voiemaritime.com/fr/a-propos/slsmc-management/annual-corporate-summaries/");TextView s=tx("Base intégrée : 9 septembre 2026",12,MUTED,true);s.setPadding(0,dp(12),0,0);content.addView(s);}
}
